  "К пульту мастера ↗": "GM Dashboard ↗",
  "План виден только мастеру. Добавьте подготовленные сцены, запасные встречи и переходы по исходам. Запуск плана доступен в пульте мастера.": "Only the GM can see this plan. Add prepared scenes, backup encounters, and outcome-based transitions. Launch the plan from the GM dashboard.",
