  "Последовательность сцен": "Scene sequence",
  "Обязательные и возможные сцены идут по порядку. Запасные сцены открываются через развилку или ручной переход. Если у шага заданы развилки, следующий переход выбирается из них по исходу текущей сцены.": "Required and optional scenes run in order. Backup scenes are accessed through a branch or manual transition. When a step has branches, the next transition is chosen from them according to the current scene's outcome.",
