  "Джеральд Светоносный": "Gerald Lightbringer",
  "Паладин-танк ближнего боя. Сдерживает врагов щитом.": "A melee paladin tank who holds enemies back with his shield.",
  "Активная способность: +40% брони и бонус Харизмы союзникам (5 маны) [КД: 3 р.]": "Active: +40% armor and a Charisma bonus for allies (5 mana) [CD: 3 rounds]",
  "Активная способность: +30% брони и возврат урона от Мудрости (6 маны) [КД: 3 р.]": "Active: +30% armor and Wisdom-based damage reflection (6 mana) [CD: 3 rounds]",
  "Пассивка: Спасение от смерти и хил от Телосложения (0 маны)": "Passive: Constitution-based death prevention and healing (0 mana)",
  "Пассивка: +30% к шансу блока щитом от Ловкости (0 маны)": "Passive: +30% Dexterity-based shield block chance (0 mana)",
  "Пассивка: Регенерация ХП в блоке от Телосложения (0 маны)": "Passive: Constitution-based HP regeneration while blocking (0 mana)",
  "Ультимейт: Обрушивает карающий клинок: 200 Чистого урона [КД: 5 р.]": "Ultimate: Calls down a punishing blade for 200 true damage [CD: 5 rounds]",
  "Зефира (Маг-Лучник)": "Zefira (Mage Archer)",
  "Дальнобойный маг энергии. Бьёт по площади и замедляет.": "A long-range energy mage with area damage and slows.",
  "Активная способность: Энергетический молот наносит d12+INT магии и оглушает (5 маны) [КД: 3 р.]": "Active: An energy hammer deals d12+INT magic damage and stuns (5 mana) [CD: 3 rounds]",
  "Активная способность: Вращающиеся мечи дают +30% резов и наносят d8 магии (4 маны) [КД: 4 р.]": "Active: Whirling blades grant +30% resistances and deal d8 magic damage (4 mana) [CD: 4 rounds]",
  "Активная способность: Телепортация на 4 клетки + бафф от Ловкости на 2 хода (3 маны) [КД: 2 р.]": "Active: Teleport 4 cells and gain a Dexterity-based buff for 2 turns (3 mana) [CD: 2 rounds]",
  "Пассивка: Снижает сопротивление магии всех врагов в радиусе на 30% (0 маны)": "Passive: Reduces all enemies' magic resistance within range by 30% (0 mana)",
  "Пассивка: Обычные выстрелы имеют 20% шанс нанести крит (0 маны)": "Passive: Basic shots have a 20% critical hit chance (0 mana)",
  "Ультимейт: Ливень энергетических копий наносит 210 урона! [КД: 5 р.]": "Ultimate: A rain of energy spears deals 210 damage! [CD: 5 rounds]",
