  "Чертог Варваров IV": "Barbarian Hall IV",
  "3 яростных варвара: 130 ХП, 25% брони, 20 урона, респаун 1 ход (инициатива 18). Доступны метание топоров и жажда крови.": "3 fierce barbarians: 130 HP, 25% armor, 20 damage, 1-turn respawn (initiative 18). Axe Throw and Bloodlust available.",
