  "Нет соединения с сервером. Обновите страницу.": "No server connection. Refresh the page.",
  "Свободное перемещение. Каждый переход героя на другую клетку полностью восстанавливает ХП, ману и способности. Снос возвращает 100% затрат на башню и улучшения.": "Free movement. Every move to a different cell fully restores the hero's HP, mana and abilities. Demolition refunds 100% of tower and upgrade investment.",
  "Стандартные правила: движение по скорости один раз за раунд, обычные затраты маны и перезарядки. Возврат за снос — 60% цены текущего уровня башни.": "Standard rules: one speed-limited move per round, normal mana costs and cooldowns. Demolition refunds 60% of the current tower level's price.",
