  "button type=\"button\" id=\"scene-note-close\" aria-label=\"Закрыть\"": "button type=\"button\" id=\"scene-note-close\" aria-label=\"Close\"",
  "В новой сцене все заметки скрыты. Мастер может раскрыть только название, координаты и текст для игроков. Проверка и секрет остаются у мастера.": "All notes in a new scene are hidden. The GM can reveal only the title, coordinates and player text. Checks and secrets remain with the GM.",
  "Удалить заметку": "Delete note",
  "Отбросить несохранённые изменения сцены?": "Discard unsaved scene changes?",
  "Соединение потеряно. Черновик сохранён в этом окне. Для подключения нажмите «Загрузить с сервера».": "Connection lost. Your draft remains in this window. Click “Load from server” to reconnect.",
  "Не удалось подключиться к серверу.": "Could not connect to the server.",
  "Текущее поле скопировано в черновик. Состояние партии не изменилось.": "Current map copied to draft. The game state has not changed.",
  "В другом окне сохранена новая версия. Ваш черновик остался здесь. Перед сохранением загрузите библиотеку с сервера.": "A new version was saved in another window. Your draft remains here. Load the library from the server before saving.",
  "Библиотека сохранена. Сцену можно открыть из пульта мастера.": "Library saved. Open the scene from the GM dashboard.",
