  "Волны не добавлены. Можно использовать только заранее расставленных врагов.": "No waves added. You can use only pre-placed enemies.",
  "Новая сцена": "New scene",
  "Черновик создан. Добавьте карту, врагов и заметки.": "Draft created. Add a map, enemies and notes.",
  "Копия создана. Сохраните её в библиотеку.": "Copy created. Save it to the library.",
  "Удалить сохранённую сцену «": "Delete saved scene “",
  "»? Текущая партия продолжится без изменений.": "”? The current game will continue unchanged.",
  "Уменьшить карту? Содержимое клеток за новой границей будет удалено из черновика.": "Shrink the map? Cells outside the new boundary will be removed from the draft.",
  "Эта волна уже добавлена или достигнут предел 200 волн.": "This wave has already been added, or the 200-wave limit has been reached.",
  "Выберите клетку на карте, чтобы применить инструмент.": "Select a map cell to apply the tool.",
