  "скрытая": "hidden",
  "Добавьте задачу «Удержать мост» или счётчик спасённых жителей.": "Add an objective such as “Hold the Bridge” or a counter for rescued villagers.",
  "Исходы сцены": "Scene outcomes",
  "Определять исход автоматически по основным целям": "Determine outcome automatically from primary objectives",
  "Полный успех: выполнены все основные цели. Частичный успех: все основные цели разрешены, часть выполнена, часть провалена. Поражение: все основные цели провалены. Мастер может выбрать исход вручную.": "Full success: all primary objectives completed. Partial success: all primary objectives resolved, some completed and some failed. Defeat: all primary objectives failed. The GM can choose an outcome manually.",
  " · текст для игроков": " · player text",
  "после подтверждения мастера": "after GM confirmation",
  "автоматически": "automatically",
