  "Откатить до этого действия": "Roll back to this action",
  "Отменяет выбранное действие и всё, что произошло после него. История очищается при ручном изменении мира мастером, начале нового раунда или перезапуске сервера.": "Undoes the selected action and everything after it. History clears when the GM changes the world, a new round starts or the server restarts.",
