  "Также отменить ожидающие подкрепления": "Also cancel pending reinforcements",
  "Без наград и эффектов гибели. Герои, башни и ресурсы сохраняются.": "No rewards or death effects. Heroes, towers and resources are preserved.",
  "Удалить врагов": "Remove enemies",
