  "Запустить волну": "Launch wave",
  "Переключайте периоды игры вручную. Во время подготовки враги ждут начала игры.": "Switch game periods manually. During preparation, enemies wait for play to begin.",
  "Текущая карта": "Current map",
  "Свободное перемещение. Каждый ход на новую клетку полностью восстанавливает ХП, ману и способности героя. Снос башни возвращает 100% стоимости постройки и улучшений.": "Free movement. Every move to a different cell fully restores the hero's HP, mana and abilities. Demolition refunds 100% of tower and upgrade investment.",
  "Стандартные правила: одно перемещение в пределах скорости за раунд, штатный расход маны и перезарядок. Снос башни возвращает 60% стоимости текущего уровня.": "Standard rules: one speed-limited move per round, normal mana costs and cooldowns. Demolition refunds 60% of the current tower level's price.",
  "В периоде подготовки любой игрок и мастер могут менять общий арсенал: до 5 типов со всеми улучшениями. Перед удалением типа сначала снесите его башни на поле.": "During preparation, any player and the GM can edit the shared roster: up to 5 types with all upgrades. Demolish a type's towers before removing it.",
