  "Черновик виден только мастеру. Игроки продолжают текущую сцену. Запуск сохранённой сцены — из пульта мастера.": "Only the GM can see the draft. Players continue the current scene. Open a saved scene from the GM dashboard.",
  "Скопировать карту": "Copy current map",
  "Библиотека": "Library",
  "Сохраняет карту, расстановку врагов, волны, стартовые ресурсы и заметки. Герои и текущий бой в шаблон не входят.": "Saves the map, enemy placement, waves, starting resources and notes. Heroes and current combat are not included in the template.",
  "Создайте сцену или скопируйте карту текущей игры.": "Create a scene or copy the current map.",
  "Тип сцены": "Scene type",
  "Арсенал башен команды · до 5 типов": "Team tower roster · up to 5 types",
  "Тип карточки": "Card type",
  "Выбор клетки": "Select cell",
  "Нажмите на клетку, чтобы увидеть её состав.": "Click a cell to see its contents.",
  "Координаты начинаются с 0. Для запуска соедините все точки спавна с замком дорогой; диагонали не допускаются.": "Coordinates start at 0. To launch, connect all spawns to the castle with a road; no diagonals.",
  "Эта расстановка отделена от запуска волн. При открытии сцены враги ждут в периоде подготовки.": "This placement is separate from wave launches. When the scene opens, enemies wait during preparation.",
  "Добавляйте копии волн каталога. Их состав и порядок сохраняются в сцене отдельно от текущей игры.": "Add copies of catalog waves. Their composition and order are saved in the scene separately from the current game.",
  "В новой сцене все заметки скрыты. Мастер может открыть игрокам только название, координаты и текст для игроков. Проверки и секреты остаются у мастера.": "All notes in a new scene are hidden. The GM can reveal only the title, coordinates and player text. Checks and secrets remain with the GM.",
