  "Награда:": "Reward:",
  "Последняя группа:": "Last group:",
  "Группы врагов": "Enemy groups",
  "Задержка 0 спавнится при старте волны. Задержка 1 — на первом Ходе волны, 2 — на втором. Группы распределяются по точкам спавна карты.": "Delay 0 spawns when the wave starts. Delay 1 spawns on the first Wave Turn, 2 on the second. Groups are distributed across the map's spawn points.",
