  "<form id=\"live-note-form\"><div class=\"section-heading\"><h2 id=\"live-note-title\">GM Note</h2><button type=\"button\" id=\"live-note-close\" aria-label=\"Close\">✕</button></div><p class=\"muted\">Players receive only the title, coordinates and text of revealed notes. Secrets, checks and their outcomes remain with the GM.</p><div id=\"live-note-fields\" class=\"scene-note-fields\"></div><p id=\"live-note-error\" role=\"status\" class=\"note-error\" hidden></p><div class=\"button-row\"><button type=\"submit\" class=\"primary\">Save note</button><button type=\"button\" id=\"live-note-delete\" class=\"danger-outline\">Delete</button></div></form>": "<form id=\"live-note-form\"><div class=\"section-heading\"><h2 id=\"live-note-title\">Заметка мастера</h2><button type=\"button\" id=\"live-note-close\" aria-label=\"Закрыть\">✕</button></div><p class=\"muted\">Игрокам передаются только название, координаты и текст раскрытой заметки. Секрет, проверка и её исходы остаются у мастера.</p><div id=\"live-note-fields\" class=\"scene-note-fields\"></div><p id=\"live-note-error\" role=\"status\" class=\"note-error\" hidden></p><div class=\"button-row\"><button type=\"submit\" class=\"primary\">Сохранить заметку</button><button type=\"button\" id=\"live-note-delete\" class=\"danger-outline\">Удалить</button></div></form>",
