  "Coordinates start at 0. To launch, connect all spawns to the castle with a road; no diagonals.": "Координаты начинаются с 0. Для запуска соедините все точки спавна с замком дорогой; диагонали не допускаются.",
  "Enemy placement": "Расстановка врагов",
