  "All notes in a new scene are hidden. The GM can reveal only the title, coordinates and player text. Checks and secrets remain with the GM.": "В новой сцене все заметки скрыты. Мастер может открыть игрокам только название, координаты и текст для игроков. Проверки и секреты остаются у мастера.",
  "Delete note": "Удалить заметку",
  "Discard unsaved scene changes?": "Отбросить несохранённые изменения сцены?",
  "Connection lost. Your draft remains in this window. Click “Load from server” to reconnect.": "Соединение потеряно. Черновик сохранён в этом окне. Для подключения нажмите «Загрузить с сервера».",
