  "Full success: all primary objectives completed. Partial success: all primary objectives resolved, some completed and some failed. Defeat: all primary objectives failed. The GM can choose an outcome manually.": "Полный успех: выполнены все основные цели. Частичный успех: все основные цели разрешены, часть выполнена, часть провалена. Поражение: все основные цели провалены. Мастер может выбрать исход вручную.",
