  "Secrets and GM notes": "Секреты и заметки мастера",
  "List phases in descending HP threshold order: 100, 50, 20. In play, the GM receives a reminder; enemy stats do not change automatically.": "Фазы перечисляются по убыванию порога ХП: 100, 50, 20. В игре мастер получает напоминание; характеристики врага автоматически не меняются.",
